//! Action-context v1 preimage encoding. Hash the returned bytes with SHA-256.
//! This is separate from VIR-Core's existing Keccak hash domains.

/// Validate the fixed 21 ABI words and return the canonical SHA-256 preimage.
#[must_use]
pub fn action_context_preimage_v1(words: &[[u8; 32]; 21]) -> Option<Vec<u8>> {
    let zero = [0_u8; 32];
    for (index, value) in words.iter().enumerate().take(13) {
        if index != 3 && *value == zero {
            return None;
        }
    }
    let mut scheme_one = zero;
    scheme_one[31] = 1;
    let mut scheme_two = zero;
    scheme_two[31] = 2;
    let root_prefix = if words[13] == scheme_one {
        12
    } else if words[13] == scheme_two {
        4
    } else {
        return None;
    };
    if words[0][..root_prefix].iter().any(|byte| *byte != 0)
        || [14, 15, 16, 20].iter().any(|index| words[*index] == zero)
        || words[19] <= words[18]
    {
        return None;
    }
    let mut encoded = b"VAMS:ACTION-CONTEXT:v1\0".to_vec();
    for word in words {
        encoded.extend_from_slice(word);
    }
    Some(encoded)
}

/// Decode only the canonical v1 frame, preserving the full unsigned words.
/// This parser does not authenticate policy, actor consent or execution evidence.
#[must_use]
pub fn decode_action_context_v1(encoded: &[u8]) -> Option<[[u8; 32]; 21]> {
    let domain = b"VAMS:ACTION-CONTEXT:v1\0";
    if encoded.len() != domain.len() + 21 * 32 || !encoded.starts_with(domain) {
        return None;
    }
    let mut words = [[0_u8; 32]; 21];
    for (word, chunk) in words
        .iter_mut()
        .zip(encoded[domain.len()..].chunks_exact(32))
    {
        word.copy_from_slice(chunk);
    }
    action_context_preimage_v1(&words).map(|_| words)
}

